  private static int value(int index) {
    return ((ENTRIES.charAt(index * 2) - 0x100) << 15) | (ENTRIES.charAt(index * 2 + 1) - 0x100);
  }

  static final int EMOJI = 1;
  static final int EMOJI_PRESENTATION = 2;
  static final int EMOJI_MODIFIER = 4;
  static final int EMOJI_MODIFIER_BASE = 8;
  static final int EMOJI_COMPONENT = 16;
  static final int EXTENDED_PICTOGRAPHIC = 32;

  static boolean hasProperty(int codePoint, int property) {
    return (entry(codePoint) & property) != 0;
  }

  private static int entry(int codePoint) {
    if (codePoint < 0 || codePoint > 0x10ffff) return 0;
    int page = codePoint >>> 10;
    int low = PAGES.charAt(page) - 0x100;
    int high = PAGES.charAt(page + 1) - 0x100 + 1;
    while (low + 1 < high) {
      int middle = (low + high) >>> 1;
      if ((value(middle) >>> 6) <= codePoint) low = middle;
      else high = middle;
    }
    return value(low) & 63;
  }
